ckbox" name="remove_hero_image_path" value="1" style="width:auto"> Hapus foto</label><button class="btn btn-small" type="submit" style="margin-top:8px">Simpan</button></form></td><td><form class="inline" method="post" action="<?= site_url('admin/yayasan/sekolah') ?>" onsubmit="return confirm('Ubah status sekolah ini?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $school['id'] ?>"><input type="hidden" name="action" value="<?= (int) $school['is_active'] === 1 ? 'deactivate' : 'activate' ?>"><button class="btn btn-small <?= (int) $school['is_active'] === 1 ? 'btn-warn' : '' ?>" type="submit"><?= (int) $school['is_active'] === 1 ? 'Nonaktifkan' : 'Aktifkan' ?></button></form></td></tr><?php endforeach; endif ?>
